from datetime import datetime
now = datetime.now()
now_year, now_month = now.year, now.month

# verification: remaining expired cards after deletions
verification = {}

# supervisor cards
sup_cards = apis.supervisor.show_payment_cards()
verification['supervisor'] = {'total': len(sup_cards), 'expired': []}
for c in sup_cards:
    exp_y = int(c['expiry_year']); exp_m=int(c['expiry_month'])
    is_expired = (exp_y < now_year) or (exp_y==now_year and exp_m<=now_month)
    if is_expired:
        verification['supervisor']['expired'].append(c)

# app-specific cards
apps_to_check = ['amazon','venmo','spotify']
for app in apps_to_check:
    token = access_tokens.get(app)
    cards = getattr(apis, app).show_payment_cards(access_token=token)
    expired = []
    for c in cards:
        exp_y=int(c['expiry_year']); exp_m=int(c['expiry_month'])
        is_expired=(exp_y<now_year) or (exp_y==now_year and exp_m<=now_month)
        if is_expired:
            expired.append(c)
    verification[app] = {'total': len(cards), 'expired_count': len(expired), 'expired_card_ids':[int(c['payment_card_id']) for c in expired], 'expired_summary':[{ 'card_name':c.get('card_name'),'expiry_year':c.get('expiry_year'),'expiry_month':c.get('expiry_month')} for c in expired]}

print('verification', verification)
